 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Complete interrupted horizontal runs when the nearest colored cells
    # on both sides of a gap have the same color.
    for r in range(h):
        c = 0
        while c < w:
            if out[r][c] != 0:
                c += 1
                continue
            start = c
            while c < w and out[r][c] == 0:
                c += 1
            if start > 0 and c < w and out[r][start - 1] == out[r][c]:
                color = out[r][start - 1]
                for x in range(start, c):
                    out[r][x] = color

    # At the columns marked by vertical rays, extend each horizontal stripe
    # upward to the preceding stripe (or the top edge). Existing cells remain.
    for c in range(w):
        vertical_rows = [r for r in range(h) if grid[r][c] != 0]
        if not any(
            any(grid[r][c] != 0 for r in range(a, b))
            for a, b in [(0, h)]
        ):
            continue
        # Require a vertical marker: at least two contiguous cells in this column.
        is_marker = any(
            r + 1 < h and grid[r][c] != 0 and grid[r + 1][c] != 0
            for r in range(h)
        )
        if not is_marker:
            continue
        sources = [r for r in range(h) if out[r][c] != 0 and
                   sum(1 for x in out[r] if x != 0) >= 2]
        previous = -1
        for r in sources:
            color = out[r][c]
            for y in range(previous + 1, r + 1):
                if out[y][c] == 0:
                    out[y][c] = color
            previous = r
    return out
